//! Everyday rundown edits against upstream's own rundown service (RIIR 7,
//! plan 015). `fixtures/rundown_edits.json` is generated by
//! scripts/upstream-oracle/gen-rundown_edits.ts: a starting rundown and a
//! script of edits, with the processed rundown upstream had after each one.
//! Here the same edits go through our REST routes, as the editor sends them.

use std::collections::{BTreeMap, BTreeSet};

use ontime_core::api::{handle, ApiRequest, HttpMethod};
use ontime_core::project::Project;
use ontime_core::rundown::Rundown;
use serde::Deserialize;
use serde_json::{json, Map, Value};

const NOW: i64 = 1_700_000_000_000;

#[derive(Deserialize)]
struct Step {
    edit: Value,
    error: Option<String>,
    after: Value,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    rundown: Value,
    steps: Vec<Step>,
}

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

/// The fields compared, as the generator keeps them.
const KEEP: &[&str] = &[
    "type",
    "parent",
    "entries",
    "title",
    "cue",
    "skip",
    "flag",
    "colour",
    "countToEnd",
    "linkStart",
    "timeStrategy",
    "timeStart",
    "timeEnd",
    "duration",
    "delay",
    "gap",
    "dayOffset",
    "targetDuration",
];

/// Upstream's results this fork deliberately does not follow, as
/// `(case, step, what)` with why. `what` is `"*"` for the whole step.
const DELIBERATE: &[(&str, usize, &str, &str)] = &[];

fn project_with(rundown: &Value) -> Project {
    let mut rundown: Rundown =
        serde_json::from_value(rundown.clone()).expect("an upstream rundown");
    rundown.recompute();
    let mut project = Project {
        loaded: rundown.id.clone(),
        ..Default::default()
    };
    project.rundowns.insert(rundown.id.clone(), rundown);
    project
}

/// The REST call the editor makes for an edit.
fn request(rundown: &str, edit: &Value) -> ApiRequest {
    let text = |key: &str| edit[key].as_str().unwrap_or_default().to_string();
    let base = format!("/data/rundowns/{rundown}");
    let (method, path, body) = match edit["do"].as_str().unwrap_or_default() {
        "add" => (
            HttpMethod::Post,
            format!("{base}/entry"),
            edit["entry"].clone(),
        ),
        "edit" => (
            HttpMethod::Put,
            format!("{base}/entry"),
            edit["patch"].clone(),
        ),
        "batch" => (
            HttpMethod::Put,
            format!("{base}/batch"),
            json!({ "ids": edit["ids"], "data": edit["data"] }),
        ),
        "delete" => (
            HttpMethod::Delete,
            format!("{base}/entries"),
            json!({ "ids": edit["ids"] }),
        ),
        "reorder" => (
            HttpMethod::Patch,
            format!("{base}/reorder"),
            json!({ "entryId": edit["entryId"], "destinationId": edit["destinationId"], "order": edit["order"] }),
        ),
        "swap" => (
            HttpMethod::Patch,
            format!("{base}/swap"),
            json!({ "from": edit["from"], "to": edit["to"] }),
        ),
        "applydelay" => (
            HttpMethod::Patch,
            format!("{base}/applydelay/{}", text("id")),
            json!({}),
        ),
        "clone" => (
            HttpMethod::Post,
            format!("{base}/clone/{}", text("id")),
            edit.get("options").cloned().unwrap_or(json!({})),
        ),
        "group" => (
            HttpMethod::Post,
            format!("{base}/group"),
            json!({ "ids": edit["ids"] }),
        ),
        "ungroup" => (
            HttpMethod::Post,
            format!("{base}/ungroup/{}", text("id")),
            json!({}),
        ),
        other => panic!("unknown edit {other}"),
    };
    ApiRequest {
        method,
        path,
        body,
        token: None,
        master_token: None,
        room_is_new: false,
        member: None,
    }
}

/// Our rundown in the generator's shape.
fn snapshot(project: &Project, rundown: &str) -> Value {
    let rundown = &project.rundowns[rundown];
    let entries: Map<String, Value> = rundown
        .entries
        .iter()
        .map(|(id, entry)| {
            let kept: Map<String, Value> = KEEP
                .iter()
                .filter_map(|key| {
                    entry
                        .get(*key)
                        .map(|value| (key.to_string(), value.clone()))
                })
                .collect();
            (id.clone(), Value::Object(kept))
        })
        .collect();
    json!({ "order": rundown.order, "flatOrder": rundown.flat_order, "entries": entries })
}

/// Ids either side made up (a clone, a new group) are random, so they are
/// renamed `new-1`, `new-2`… in the order they appear.
fn normalised(snapshot: &Value, known: &BTreeSet<String>) -> Value {
    let mut names = BTreeMap::new();
    let order = snapshot["flatOrder"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let top = snapshot["order"].as_array().cloned().unwrap_or_default();
    for id in order.iter().chain(top.iter()).filter_map(Value::as_str) {
        if !known.contains(id) && !names.contains_key(id) {
            names.insert(id.to_string(), format!("new-{}", names.len() + 1));
        }
    }
    let rename = |id: &str| names.get(id).cloned().unwrap_or_else(|| id.to_string());
    fn walk(value: &Value, rename: &dyn Fn(&str) -> String) -> Value {
        match value {
            Value::String(text) => Value::String(rename(text)),
            Value::Array(items) => {
                Value::Array(items.iter().map(|item| walk(item, rename)).collect())
            }
            Value::Object(map) => Value::Object(
                map.iter()
                    .map(|(key, value)| {
                        let value = match key.as_str() {
                            // only ids are renamed, never a title or a cue
                            "parent" | "entries" | "order" | "flatOrder" => walk(value, rename),
                            _ if value.is_object() => walk(value, rename),
                            _ => value.clone(),
                        };
                        (rename(key), value)
                    })
                    .collect(),
            ),
            other => other.clone(),
        }
    }
    walk(snapshot, &rename)
}

/// Numbers compared by value, so 600000 and 600000.0 agree. A field one side
/// leaves out and the other holds as `""` or `false` is the same entry: the
/// fixture's starting events are upstream's partial mocks, which fill in on
/// the first edit. A missing number is never taken for 0.
fn same(a: &Value, b: &Value) -> bool {
    let blank = |v: &Value| matches!(v, Value::Null) || v == &json!("") || v == &json!(false);
    match (a.as_f64(), b.as_f64()) {
        (Some(x), Some(y)) => x == y,
        _ if blank(a)
            && blank(b)
            && !(a.is_string() && b.is_boolean())
            && !(a.is_boolean() && b.is_string()) =>
        {
            true
        }
        _ => a == b,
    }
}

fn differences(upstream: &Value, ours: &Value) -> Vec<String> {
    let mut found = Vec::new();
    for key in ["order", "flatOrder"] {
        if upstream[key] != ours[key] {
            found.push(format!(
                "{key}: upstream {}, ours {}",
                upstream[key], ours[key]
            ));
        }
    }
    let empty = Map::new();
    let theirs = upstream["entries"].as_object().unwrap_or(&empty);
    let mine = ours["entries"].as_object().unwrap_or(&empty);
    let ids: BTreeSet<&String> = theirs.keys().chain(mine.keys()).collect();
    for id in ids {
        let (Some(want), Some(got)) = (theirs.get(id), mine.get(id)) else {
            found.push(format!(
                "{id}: only in {}",
                if theirs.contains_key(id) {
                    "upstream"
                } else {
                    "ours"
                }
            ));
            continue;
        };
        for key in KEEP {
            let want = want.get(*key).unwrap_or(&Value::Null);
            let got = got.get(*key).unwrap_or(&Value::Null);
            if !same(want, got) {
                found.push(format!("{id}.{key}: upstream {want}, ours {got}"));
            }
        }
    }
    found
}

#[test]
fn everyday_edits_match_upstream() {
    let fixture: Fixture =
        serde_json::from_str(include_str!("fixtures/rundown_edits.json")).unwrap();
    let mut failures = Vec::new();

    for case in &fixture.cases {
        let mut project = project_with(&case.rundown);
        let rundown_id = case.rundown["id"].as_str().unwrap().to_string();
        let mut known: BTreeSet<String> = case.rundown["entries"]
            .as_object()
            .unwrap()
            .keys()
            .cloned()
            .collect();

        for (n, step) in case.steps.iter().enumerate() {
            if let Some(id) = step.edit["entry"]["id"].as_str() {
                known.insert(id.to_string());
            }
            let response = handle(&mut project, &request(&rundown_id, &step.edit), NOW);
            let at = format!("{} / step {}", case.name, n + 1);
            if DELIBERATE
                .iter()
                .any(|(name, s, what, _)| *name == case.name && *s == n + 1 && *what == "*")
            {
                continue;
            }
            match (&step.error, response.status >= 400) {
                (Some(_), true) | (None, false) => {}
                (Some(error), false) => {
                    failures.push(format!("{at}: upstream refused ({error}), ours accepted"))
                }
                (None, true) => failures.push(format!(
                    "{at}: upstream accepted, ours refused ({}: {:?})",
                    response.status, response.body
                )),
            }
            let upstream = normalised(&step.after, &known);
            let ours = normalised(&snapshot(&project, &rundown_id), &known);
            for difference in differences(&upstream, &ours) {
                let field = difference.split(':').next().unwrap_or_default().to_string();
                let deliberate = DELIBERATE
                    .iter()
                    .any(|(name, s, what, _)| *name == case.name && *s == n + 1 && *what == field);
                if !deliberate {
                    failures.push(format!("{at}: {difference}"));
                }
            }
        }
    }

    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
